/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to a PDF file. &IsAuthorized = SecGAMIsAuthByFunctionalityKey.Udp(!'<Check_Is_Authenticated>') If &IsAuthorized
LoadWWPContext.Call(&WWPContext)
Do 'LoadGridState'
&Title = "Lista de Rancho"
//Report Template Source Header &AppName = "DVelop Software Solutions" &Phone = !"+1 550 8923" &Mail = !"info@mail.com" &Website = !"http://www.web.com" &AddressLine1 = !"French Boulevard 2859" &AddressLine2 = !"Downtown" &AddressLine3 = !"Paris, France" Print printTitle End Footer &PageInfo = "Page: " + &Page.ToString().Trim() &DateInfo = "Date: " + &Today.ToFormattedString() Print printFooter End
Do 'PrintFilters'
Do 'PrintColumnTitles'
Do 'PrintData'
Do 'PrintFooter'
EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'RANCHODATAENVIO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &RanchoDataEnvio1.FromString(&GridStateDynamicFilter.Value) &RanchoDataEnvio_To1.FromString(&GridStateDynamicFilter.ValueTo) If not &RanchoDataEnvio1.IsEmpty() OR not &RanchoDataEnvio_To1.IsEmpty() &FixedValueOperatorDsc = "Envio" Do Case Case &DynamicFiltersOperator1 = 0 &FixedValueOperatorValue = "WWP_FilterPast" print printBlockFixedValueOperator Case &DynamicFiltersOperator1 = 1 &FixedValueOperatorValue = "WWP_FilterToday" print printBlockFixedValueOperator Case &DynamicFiltersOperator1 = 2 &FixedValueOperatorValue = "WWP_FilterInTheFuture" print printBlockFixedValueOperator Case &DynamicFiltersOperator1 = 3 &FilterRanchoDataEnvioDescription = format('%1 (%2)', "Envio", "WWP_FilterRange") &RanchoDataEnvio = &RanchoDataEnvio1 print printBlockFilterRanchoDataEnvio &FilterRanchoDataEnvioDescription = format('%1 (%2) %3', "Envio", "WWP_FilterRange", "") &RanchoDataEnvio = &RanchoDataEnvio_To1 print printBlockFilterRanchoDataEnvio EndCase EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'RANCHODATAENVIO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &RanchoDataEnvio2.FromString(&GridStateDynamicFilter.Value) &RanchoDataEnvio_To2.FromString(&GridStateDynamicFilter.ValueTo) If not &RanchoDataEnvio2.IsEmpty() OR not &RanchoDataEnvio_To2.IsEmpty() &FixedValueOperatorDsc = "Envio" Do Case Case &DynamicFiltersOperator2 = 0 &FixedValueOperatorValue = "WWP_FilterPast" print printBlockFixedValueOperator Case &DynamicFiltersOperator2 = 1 &FixedValueOperatorValue = "WWP_FilterToday" print printBlockFixedValueOperator Case &DynamicFiltersOperator2 = 2 &FixedValueOperatorValue = "WWP_FilterInTheFuture" print printBlockFixedValueOperator Case &DynamicFiltersOperator2 = 3 &FilterRanchoDataEnvioDescription = format('%1 (%2)', "Envio", "WWP_FilterRange") &RanchoDataEnvio = &RanchoDataEnvio2 print printBlockFilterRanchoDataEnvio &FilterRanchoDataEnvioDescription = format('%1 (%2) %3', "Envio", "WWP_FilterRange", "") &RanchoDataEnvio = &RanchoDataEnvio_To2 print printBlockFilterRanchoDataEnvio EndCase EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'RANCHODATAENVIO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &RanchoDataEnvio3.FromString(&GridStateDynamicFilter.Value) &RanchoDataEnvio_To3.FromString(&GridStateDynamicFilter.ValueTo) If not &RanchoDataEnvio3.IsEmpty() OR not &RanchoDataEnvio_To3.IsEmpty() &FixedValueOperatorDsc = "Envio" Do Case Case &DynamicFiltersOperator3 = 0 &FixedValueOperatorValue = "WWP_FilterPast" print printBlockFixedValueOperator Case &DynamicFiltersOperator3 = 1 &FixedValueOperatorValue = "WWP_FilterToday" print printBlockFixedValueOperator Case &DynamicFiltersOperator3 = 2 &FixedValueOperatorValue = "WWP_FilterInTheFuture" print printBlockFixedValueOperator Case &DynamicFiltersOperator3 = 3 &FilterRanchoDataEnvioDescription = format('%1 (%2)', "Envio", "WWP_FilterRange") &RanchoDataEnvio = &RanchoDataEnvio3 print printBlockFilterRanchoDataEnvio &FilterRanchoDataEnvioDescription = format('%1 (%2) %3', "Envio", "WWP_FilterRange", "") &RanchoDataEnvio = &RanchoDataEnvio_To3 print printBlockFilterRanchoDataEnvio EndCase EndIf EndCase EndIf EndIf EndIf If not (&TFRanchoAno.IsEmpty() AND &TFRanchoAno_To.IsEmpty()) print printBlockTFRanchoAno &TFRanchoAno_To_Description = format('%1 (%2)', "Ano", "WWP_TSTo") print printBlockTFRanchoAno_To EndIf &TFRanchoMes_Sels.FromJson(&TFRanchoMes_SelsJson) If not &TFRanchoMes_Sels.Count = 0 &i = 1 For &TFRanchoMes_Sel in &TFRanchoMes_Sels If &i = 1 &TFRanchoMes_SelDscs = '' Else &TFRanchoMes_SelDscs += ', ' EndIf &FilterTFRanchoMes_SelValueDescription = &TFRanchoMes_Sel.EnumerationDescription()
&TFRanchoMes_SelDscs += &FilterTFRanchoMes_SelValueDescription &i += 1 EndFor print printBlockTFRanchoMes_Sel EndIf If not (&TFRanchoDataEnvio.IsEmpty() AND &TFRanchoDataEnvio_To.IsEmpty()) print printBlockTFRanchoDataEnvio &TFRanchoDataEnvio_To_Description = format('%1 (%2)', "Envio", "WWP_TSTo") print printBlockTFRanchoDataEnvio_To EndIf &TFRanchoStatus_Sels.FromJson(&TFRanchoStatus_SelsJson) If not &TFRanchoStatus_Sels.Count = 0 &i = 1 For &TFRanchoStatus_Sel in &TFRanchoStatus_Sels If &i = 1 &TFRanchoStatus_SelDscs = '' Else &TFRanchoStatus_SelDscs += ', ' EndIf &FilterTFRanchoStatus_SelValueDescription = &TFRanchoStatus_Sel.EnumerationDescription()
&TFRanchoStatus_SelDscs += &FilterTFRanchoStatus_SelValueDescription &i += 1 EndFor print printBlockTFRanchoStatus_Sel EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each Rancho order RanchoDataEnvio when &OrderedBy = 1 AND &OrderedDsc = False order (RanchoDataEnvio) when &OrderedBy = 1 AND &OrderedDsc = True order RanchoAno when &OrderedBy = 2 AND &OrderedDsc = False order (RanchoAno) when &OrderedBy = 2 AND &OrderedDsc = True order RanchoMes when &OrderedBy = 3 AND &OrderedDsc = False order (RanchoMes) when &OrderedBy = 3 AND &OrderedDsc = True order RanchoStatus when &OrderedBy = 4 AND &OrderedDsc = False order (RanchoStatus) when &OrderedBy = 4 AND &OrderedDsc = True
using RanchoWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &RanchoDataEnvio1, &RanchoDataEnvio_To1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2 , &DynamicFiltersOperator2, &RanchoDataEnvio2, &RanchoDataEnvio_To2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3 , &RanchoDataEnvio3, &RanchoDataEnvio_To3, &TFRanchoAno, &TFRanchoAno_To, &TFRanchoMes_Sels, &TFRanchoDataEnvio , &TFRanchoDataEnvio_To, &TFRanchoStatus_Sels) Where prefCodigo = &prefCodigo &RanchoMesDescription = RanchoMes.EnumerationDescription() &RanchoStatusDescription = RanchoStatus.EnumerationDescription()
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"RanchoWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"RanchoWWGridState")) Else &GridState.FromXml(&Session.Get(!"RanchoWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFRANCHOANO" &TFRanchoAno.FromString(&GridStateFilterValue.Value) &TFRanchoAno_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFRANCHOMES_SEL" &TFRanchoMes_SelsJson = &GridStateFilterValue.Value &TFRanchoMes_Sels.FromJson(&TFRanchoMes_SelsJson) Case &GridStateFilterValue.Name = !"TFRANCHODATAENVIO" &TFRanchoDataEnvio.FromString(&GridStateFilterValue.Value) &TFRanchoDataEnvio_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFRANCHOSTATUS_SEL" &TFRanchoStatus_SelsJson = &GridStateFilterValue.Value &TFRanchoStatus_Sels.FromJson(&TFRanchoStatus_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
